#include <smmintrin.h>
#include <wasm_simd128.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

__attribute__((noinline)) static __m128i old_conversion(__m128 v) {
    return _mm_cvttps_epi32(v);
}
__attribute__((noinline)) static __m128i new_conversion(__m128 v) {
    v128_t value = (v128_t)v;
    v128_t valid = wasm_f32x4_lt(wasm_f32x4_abs(value), wasm_f32x4_splat(2147483648.f));
    return (__m128i)wasm_v128_bitselect(wasm_i32x4_trunc_sat_f32x4(value),
                                       wasm_i32x4_splat(INT32_MIN), valid);
}
static uint64_t checked, mismatches;
static int check(uint32_t bits[4]) {
    float values[4]; int32_t a[4], b[4];
    memcpy(values, bits, sizeof(values));
    __m128 v = _mm_loadu_ps(values);
    _mm_storeu_si128((__m128i*)a, old_conversion(v));
    _mm_storeu_si128((__m128i*)b, new_conversion(v));
    for (int i=0;i<4;i++) {
        checked++;
        if(a[i]!=b[i]) {
            if(mismatches++ < 20) printf("mismatch bits=%08x old=%d new=%d\n",bits[i],a[i],b[i]);
        }
    }
    return mismatches != 0;
}
int main(void) {
    /* Both signs, every exponent, mantissa boundaries (including NaN,
     * infinities, subnormals and values adjacent to signed i32 limits). */
    for (uint32_t sign=0;sign<2;sign++) for(uint32_t exp=0;exp<256;exp++) {
        uint32_t base=(sign<<31)|(exp<<23);
        uint32_t bits[]={base,base+1,base+0x7ffffe,base+0x7fffff};
        if(check(bits)) return 1;
    }
    uint32_t rng=0x7349fa21;
    for (int n=0;n<2500000;n++) {
        uint32_t bits[4];
        for(int i=0;i<4;i++) { rng^=rng<<13; rng^=rng>>17; rng^=rng<<5; bits[i]=rng; }
        if(check(bits)) return 1;
    }
    /* Dense half-way and integer boundaries within the sampler range. */
    for(int i=-65536;i<=65536;i++) {
        float values[]={i-.0001f,i+.0001f,i-.5f,i+.5f};
        uint32_t bits[4]; memcpy(bits,values,sizeof(bits));
        if(check(bits)) return 1;
    }
    printf("checked=%llu mismatches=%llu\n",(unsigned long long)checked,(unsigned long long)mismatches);
    return mismatches != 0;
}

